        sparkDiv.className = "timeline-event-tape-sparkline";
        sparkDiv.style.position = "absolute";
        sparkDiv.style.pointerEvents = "none";
        sparkDiv.style.zIndex = String(EVENT_SPARKLINE_Z_INDEX);
